      { auteur: "Ibn ʿAbd al-Ḥakam (autre avis)", avis: "On l'ôte (recommandation ou obligation selon les lectures).", statut: "qawl" },
      { auteur: "Al-Jazūlī (d'après Ibn Farḥūn)", avis: "On tourne la large, non l'étroite ; avis dit étrange.", statut: "qawl" }
